-- AI knowledge base (AGENTS.md rule 20): stocktakes (featureslist §2).
INSERT INTO ai_knowledge_entries (
  module_key, feature_name, route_path, mobile_screen_name, mobile_nav_path, platform, page_purpose, available_actions, button_locations, required_permissions, step_by_step_instructions
) VALUES
(
  'inventory', 'Stocktakes', '/inventory/stocktakes', 'StocktakesScreen', 'Home -> Quick Actions -> Count', 'both',
  'Physical counts of a warehouse, or of one location and every location under it: cycle counts, full counts, blind counts (the counters do not see what the system expects) and spot checks. Starting a count freezes what the system expects per product, location and lot. People count by scanning a location barcode and then the products in it (each scan counts one; a lot or serial number counts that lot), or by typing a quantity; a product found where it was not expected is added. Sending it for review keeps it editable; Approve & post turns every counted line with a difference into a stock adjustment against what is on hand at that moment, so stock that moved during the count is not adjusted twice. Lines not counted change nothing. Accuracy, lines with a difference and the value found and missing are shown; the count sheet exports to CSV.',
  $kb$["plan_stocktake", "start_stocktake", "scan_count", "enter_counted_quantity", "send_stocktake_for_review", "approve_and_post_stocktake", "cancel_stocktake", "export_count_sheet"]$kb$::jsonb,
  $kb$[{"label": "New stocktake", "location": "Top-right of Inventory -> Stocktakes (create_stocktakes)"}, {"label": "Start counting", "location": "Top of the stocktake (create_stocktakes)"}, {"label": "Scan", "location": "Top of the stocktake while counting, or any USB/Bluetooth scanner (count_stocktakes)"}, {"label": "Send for review", "location": "Top of the stocktake (count_stocktakes)"}, {"label": "Approve & post", "location": "Top of the stocktake (approve_stocktakes)"}, {"label": "Count sheet", "location": "Top of the stocktake (export_stocktakes)"}]$kb$::jsonb,
  $kb$["view_stocktakes", "create_stocktakes", "count_stocktakes", "approve_stocktakes", "cancel_stocktakes", "export_stocktakes"]$kb$::jsonb,
  $kb${"web": ["Go to Inventory -> Stocktakes (/inventory/stocktakes) and click New stocktake: the warehouse, optionally one location (it includes the locations under it), the type, and Blind if the counters should not see the expected quantities.", "Open it and click Start counting: what the system expects is frozen now.", "Scan a location barcode, then the products in it, or type each counted quantity in the list. Use Not counted to see what is left and Differences to check the gaps.", "Click Send for review when done. Whoever approves checks the differences and the value found and missing, then clicks Approve & post: each difference becomes a stock adjustment."], "mobile": ["In the app open Home -> Quick Actions -> Count and choose the stocktake being counted.", "Tap Scan location and scan the location's barcode, then scan each product (or its lot or serial number); the camera stays open for the next scan until you go back.", "Tap a line to type or correct a quantity, and use Not counted to see what is left.", "Tap Done to send it for review; posting the differences is done by the approver."]}$kb$::jsonb
)
ON CONFLICT (module_key, feature_name) DO UPDATE SET
  route_path = EXCLUDED.route_path, mobile_screen_name = EXCLUDED.mobile_screen_name, mobile_nav_path = EXCLUDED.mobile_nav_path,
  platform = EXCLUDED.platform, page_purpose = EXCLUDED.page_purpose, available_actions = EXCLUDED.available_actions,
  button_locations = EXCLUDED.button_locations, required_permissions = EXCLUDED.required_permissions,
  step_by_step_instructions = EXCLUDED.step_by_step_instructions, updated_at = CURRENT_TIMESTAMP;
